#include <bits/stdc++.h>
using namespace std;
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n,m,q;cin>>n>>m>>q;vector<string>g(n);for(auto&s:g)cin>>s;int V=2*n*m;vector<vector<int>> adj(V);auto id=[&](int r,int c,int z){return z*n*m+r*m+c;};for(int r=0;r<n;r++)for(int c=0;c<m;c++){for(int z=0;z<2;z++){char need=z?'R':'B';if(g[r][c]!='.'&&g[r][c]!=need)continue;int u=id(r,c,z);int dr[2]={1,0},dc[2]={0,1};for(int t=0;t<2;t++){int x=r+dr[t],y=c+dc[t];if(x<n&&y<m&&(g[x][y]=='.'||g[x][y]==need)){int w=id(x,y,z);adj[u].push_back(w);adj[w].push_back(u);}}}if(g[r][c]=='.'){int u=id(r,c,0),v=id(r,c,1);adj[u].push_back(v);adj[v].push_back(u);}}unordered_map<int,vector<int>> cache;while(q--){int sr,sc,er,ec;long long k;cin>>sr>>sc>>er>>ec>>k;int s=id(sr,sc,0),target0=id(er,ec,0),target1=id(er,ec,1);if(!cache.count(s)){vector<int>d(V,-1);queue<int>b;d[s]=0;b.push(s);while(!b.empty()){int u=b.front();b.pop();for(int v:adj[u])if(d[v]<0){d[v]=d[u]+1;b.push(v);}}cache[s]=move(d);}auto &d=cache[s];cout<<((d[target0]>=0&&d[target0]<=k)||(d[target1]>=0&&d[target1]<=k)?"YES":"NO")<<'\n';}}}
